SELECT pk_id, id, tenant_id, people_id, metric_type, value, unit, recorded_at, source, extra_json,
       is_deleted, gmt_created, gmt_modified, gmt_deleted
FROM vital_record
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND metric_type = #{metricType}
  AND recorded_at >= #{from}
  AND recorded_at <= #{to}
  AND is_deleted = 0
ORDER BY recorded_at DESC

SELECT AVG(value)
FROM vital_record
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND metric_type = #{metricType}
  AND recorded_at >= #{from}
  AND recorded_at <= #{to}
  AND is_deleted = 0
